export const clinicalMaintenanceTopics = new Set(["health-and-medicine", "nutrition-and-diet", "neuroscience-and-psychology", "sleep-and-circadian-health", "exercise-and-sports-science", "sports-nutrition-and-supplements", "infection-immunity-and-vaccines", "mental-health-and-treatment", "reproductive-and-sexual-health", "aging-and-longevity", "cancer-prevention-and-care", "cardiovascular-metabolic-and-kidney-health", "substance-use-and-addiction"]);
export const unsupportedAppraisalClaims = new Set(["do-early-or-small-studies-often-overestimate-effects", "does-preregistration-guarantee-a-study-is-trustworthy", "do-glp-1-based-medications-produce-meaningful-weight-loss-for-adults-with-obesity"]);

function correctedSources(seed: CompleteSeedClaim): CompleteSeedClaim["sources"] {
	if (seed.slug === "do-routine-childhood-vaccines-overwhelm-or-weaken-the-immune-system") {
		return seed.sources.map(source => source.url === "https://www.cdc.gov/vaccine-safety/about/multiples.html" ? { ...source, year: 2024 } : source);
	}
	if (seed.slug === "does-induced-abortion-increase-breast-cancer-risk") {
		return seed.sources.map(source => source.url === "https://www.cancer.org/cancer/risk-prevention/medical-treatments/abortion-and-breast-cancer-risk.html" ? { ...source, year: 2024 } : source);
	}
	if (seed.slug === "does-radon-in-homes-cause-lung-cancer") {
		return seed.sources.map(source => source.url === "https://www.who.int/news-room/fact-sheets/detail/radon-and-health" ? { ...source, appraisal: "not_appraised" as const, citationCheckedAt: undefined, citationStatus: undefined, statusSources: [], note: "WHO public-health guidance identifies radon as a cause of lung cancer, with greater risk among people who smoke. No separate formal appraisal was performed by this site." } : source);
	}
	if (seed.slug === "does-the-dash-eating-plan-lower-blood-pressure") {
		return seed.sources.map(source => source.url === "https://www.nhlbi.nih.gov/health/dash-eating-plan" ? { ...source, year: 2026, appraisal: "not_appraised" as const, citationCheckedAt: undefined, citationStatus: undefined, statusSources: [], note: "NHLBI public guidance, revised February 25, 2026, describes the DASH eating pattern and the additional blood-pressure benefit of reduced sodium. No separate formal appraisal was performed by this site." } : source);
	}
	if (seed.slug === "can-vaccination-indirectly-protect-people-who-are-not-vaccinated") {
		return [...seed.sources, {
			kind: "landmark_study",
			title: "Global impact of ten-valent and 13-valent pneumococcal conjugate vaccines on invasive pneumococcal disease in all ages (the PSERENADE project): a global surveillance analysis",
			publisher: "The Lancet Infectious Diseases",
			year: 2025,
			doi: "10.1016/S1473-3099(24)00665-0",
			url: "https://researchportal.ukhsa.gov.uk/en/publications/global-impact-of-ten-valent-and-13-valent-pneumococcal-conjugate-/",
			stance: "supports",
			appraisal: "not_appraised",
			order: seed.sources.length + 1,
			note: "Surveillance analysis across 30 countries, predominantly high-income settings. Disease due to covered serotypes declined in older age groups after childhood programs, while non-vaccine serotypes increased. Not a randomized estimate of a universal herd-immunity threshold. Published in the April 2025 issue after online publication in 2024; author abstract and publication metadata checked, without a new formal appraisal."
		}];
	}
	return seed.sources;
}

export const editorialCopy: Record<string, { title?: string; bottomLine: string }> = {
	"do-childhood-vaccines-cause-autism": { bottomLine: "No. The best evidence does not support a link between childhood vaccines and autism. MMR has especially large direct studies. Other vaccines and ingredients need their own evidence, not MMR's precision. WHO retains its no-causal-link conclusion; the current CDC page stresses uncertainty and disputes broader reassurance." },
	"does-the-mmr-vaccine-cause-autism": { bottomLine: "No. Large studies comparing children find no rise in autism risk after MMR vaccination. New U.S. findings add to Danish studies and older reviews. Together they strongly argue against a meaningful increase across the population. They cannot prove exactly zero effect in every possible subgroup." },
	"is-the-mmr-vaccine-safe-and-highly-effective-at-preventing-measles": { bottomLine: "Yes. MMR is highly effective against measles and has a well-established safety record. CDC estimates 93% protection against measles after one dose and 97% after two. Reviews of the research support both its benefit and overall safety. Safe does not mean free of side effects." },
	"does-the-hpv-vaccine-prevent-cervical-cancer": { bottomLine: "Yes. HPV vaccines prevent infection with types of HPV that cause most cervical cancers. They sharply reduce changes in cells that can lead to cancer. Studies following whole populations also find less cervical cancer, especially when people are vaccinated before exposure to HPV." },
	"does-the-hpv-vaccine-cause-fertility-problems": { bottomLine: "No. Large studies and vaccine-safety reviews do not support claims that HPV vaccines cause infertility or early loss of ovarian function. HPV-related cervical cancer, and some treatments for it or its early cell changes, can threaten future fertility. That is a different risk from vaccination." },
	"does-hepatitis-b-vaccination-prevent-chronic-infection-and-liver-cancer": { bottomLine: "Yes. Hepatitis B vaccines prevent infection and many later cases of long-term liver disease and liver cancer. Vaccination works best before exposure. Early protection is especially important where the virus can pass from mother to baby or spread in early childhood." },
	"do-mrna-covid-19-vaccines-change-your-dna": { bottomLine: "There is no established evidence that these vaccines rewrite people's chromosomes. Their intended effect is temporary protein production, not gene editing. Lab findings and disputes about leftover manufacturing DNA do not show that people's chromosomes change after vaccination. This does not prove that every possible molecular event is impossible." },
	"do-covid-19-vaccines-cause-infertility": { bottomLine: "The evidence does not support a general claim that these vaccines cause infertility. Findings for the mRNA vaccines studied are reassuring. Evidence differs across vaccine types and fertility treatments. Some studies of inactivated vaccines found lower success with assisted reproduction in specific settings. Those findings need follow-up; they do not establish permanent infertility." },
	"are-covid-19-vaccines-safe-and-beneficial-during-pregnancy-and-breastfeeding": { title: "What does the evidence show about COVID-19 vaccination during pregnancy?", bottomLine: "Evidence supports vaccination during pregnancy, especially to reduce severe COVID-19. Findings for the pregnancy and infant outcomes studied are broadly reassuring. Risks and certainty still differ across outcomes and vaccines. Vaccination is also generally compatible with breastfeeding, but evidence for protecting the infant differs from vaccination during pregnancy." },
	"does-flu-vaccination-during-pregnancy-protect-pregnant-people-and-young-infants": { bottomLine: "Yes. Flu vaccination during pregnancy can protect both the pregnant person and their baby in the first months of life. Pregnancy raises the risk of severe flu. Protection varies with the season, vaccine match, timing and personal risk. The nasal-spray flu vaccine is not used during pregnancy." },
	"does-breastfeeding-reduce-infants-risk-of-infections": { bottomLine: "Generally yes. Breastfeeding is linked to fewer gut and ear infections and some severe breathing infections in infants. The clearest evidence concerns groups, not a guarantee for each baby. Exposure, premature birth, vaccines, childcare, housing and support for parents and feeding also affect risk." },
	"can-vaers-reports-prove-that-a-vaccine-caused-an-adverse-event": { bottomLine: "No. VAERS reports can warn of possible vaccine-safety problems. A report says that a health event happened after vaccination and may need study. It does not show that the vaccine caused it, how often it happens, or whether it is more common than in people who were not vaccinated." },
	"how-big-is-the-myocarditis-risk-after-mrna-covid-19-vaccination": { bottomLine: "This heart inflammation is rare but real. Risk is higher in teenage and young adult males, especially after dose two in early vaccine programs. Rates differ by product, dose, age and formulation. Many patients improve, but feeling better does not always mean heart scans return to normal. Longer-term effects remain under study." },
	"are-e-cigarettes-safe-for-kids-and-teens": { bottomLine: "No. E-cigarettes are not safe for children, teens or young adults. Most contain nicotine, which can cause dependence and harm the developing brain. Youth vaping is also linked to later cigarette use. Findings about helping adults quit smoking do not make vaping safe for young people." },
	"does-fluoride-toothpaste-prevent-cavities": { bottomLine: "Yes. Regular brushing with fluoride toothpaste helps prevent cavities in children and adults. The amount and fluoride strength should suit the child's age. Fluoride protects the teeth; brushing alone does not provide the same benefit. Young children who swallow too much can develop fluorosis, changes in the enamel of teeth still forming." },
	"do-dental-sealants-prevent-cavities-in-childrens-back-teeth": { bottomLine: "Yes. Sealants form a barrier over grooves in the chewing surfaces of back teeth. They help prevent cavities in children and teens, especially on new permanent molars. They do not replace fluoride toothpaste, brushing, dental care or checks for wear." },
	"do-all-types-of-alcoholic-drinks-increase-cancer-risk": { bottomLine: "Yes. Beer, wine, cider and spirits all contain alcohol that raises cancer risk. The body can turn it into acetaldehyde, a cancer-causing chemical. The amount and pattern of drinking matter. Red wine is not an exception." },
	"does-secondhand-smoke-cause-cancer-and-heart-disease-in-people-who-do-not-smoke": { bottomLine: "Yes. Breathing other people's smoke causes lung cancer and heart disease in people who do not smoke. Major health agencies and reviews of research agree on this. There is no risk-free level of exposure." },
	"does-radon-in-homes-cause-lung-cancer": { bottomLine: "Yes. Radon is an invisible radioactive gas that can build up indoors. Long-term exposure in homes causes lung cancer. The risk is especially high for people who smoke." },
	"does-sunscreen-use-prevent-skin-cancer": { bottomLine: "Yes, as part of sun protection. Sunscreen reduces exposure to UV rays. Trial evidence is strongest for squamous cell skin cancer and suggests protection against melanoma. Evidence is less clear for basal cell cancer. Shade and protective clothing still matter; sunscreen does not block all exposure." },
	"are-modern-sunscreens-safe-when-used-as-directed-including-chemical-sunscreens": { bottomLine: "Yes, with some U.S. regulatory uncertainty. Health and skin-care bodies still recommend FDA-regulated sunscreens used as directed. FDA has asked for more safety data on several older chemical filters. That request is not a finding that they cause harm. Mineral sunscreens are another option." },
	"should-you-rely-on-sunscreen-alone-or-are-clothing-and-shade-more-protective": { title: "How do sunscreen, clothing and shade work together for sun protection?", bottomLine: "Sunscreen helps, but guidance recommends combining it with shade, clothing, hats and sunglasses, and limiting strong midday sun. Clothing and shade reduce exposure without relying as much on perfect sunscreen use. Broad-spectrum sunscreen protects skin that remains exposed and needs reapplication." },
	"does-improving-indoor-ventilation-and-filtration-reduce-respiratory-virus-spread": { bottomLine: "Yes, as one way to reduce risk. Outdoor air, better filters and suitable portable HEPA cleaners lower virus-carrying particles indoors. Evidence for fewer illnesses is less direct than evidence for cleaner air. Benefit depends on the building, number of people, airflow and maintenance." },
	"do-structured-lifestyle-programs-prevent-or-delay-type-2-diabetes-in-adults-with-prediabetes": { bottomLine: "Yes. Structured programs can prevent or delay type 2 diabetes in adults with prediabetes or high risk. They combine support for weight loss, food choices, activity and lasting changes in habits. The strongest evidence is for organized programs, not one-time advice." },
	"does-colorectal-cancer-screening-reduce-deaths": { bottomLine: "Yes. Screening lowers deaths from bowel cancer. Some tests also prevent cancer by finding polyps that can be removed before they become cancerous. Benefit depends on testing on schedule and completing follow-up colonoscopy when a test finds a possible problem." },
	"does-cervical-cancer-screening-reduce-cervical-cancer-deaths": { bottomLine: "Yes. Screening finds early cancer or cell changes that can be treated before cancer develops. This lowers both cervical cancer cases and deaths. HPV vaccines lower future risk but do not replace screening for people in the recommended age groups." },
	"does-mammography-screening-reduce-deaths-from-breast-cancer": { bottomLine: "Yes, in the recommended age groups. Mammograms can find cancers earlier and lower breast-cancer deaths. They do not prevent cancer. They can also cause false alarms and detect cancers that would never cause harm. U.S. USPSTF guidance recommends screening every two years from ages 40 to 74 for people at average risk." },
	"does-folic-acid-before-and-early-in-pregnancy-prevent-neural-tube-defects": { bottomLine: "Yes. Taking folic acid before conception and in early pregnancy lowers the risk of serious brain and spine defects, including spina bifida. Timing matters: the neural tube closes very early, often before someone knows they are pregnant." },
	"does-routine-imaging-improve-uncomplicated-low-back-pain": { bottomLine: "Usually no. Early X-rays, CT or MRI do not improve ordinary low back pain or function when there are no warning signs. Scans still matter when symptoms suggest cancer, infection, fracture, serious nerve damage or another urgent cause. A specialist may also need imaging if it would change treatment." },
	"does-spinal-manipulation-help-low-back-pain": { bottomLine: "Sometimes, modestly. Spinal manipulation can help some short- or long-term low back pain. Average benefits are small to moderate and similar to other non-surgical treatments. It does not replace checks for serious causes. Benefit for back pain is not evidence that it treats asthma, infections or high blood pressure." },
	"does-positive-airway-pressure-help-adults-with-obstructive-sleep-apnea": { bottomLine: "Yes. CPAP and related devices keep the airway open during sleep. They reduce breathing pauses and daytime sleepiness and improve sleep-related quality of life. They can also modestly lower blood pressure in some patients. They do not guarantee protection from heart attacks or strokes." },
	"does-low-dose-ct-screening-reduce-lung-cancer-deaths-in-high-risk-adults": { bottomLine: "Yes, for selected adults with a substantial smoking history. Low-dose CT screening lowers lung-cancer deaths in this group, not the whole population. Possible harms include false alarms, radiation, follow-up procedures and finding cancers that would never cause harm. Eligibility and a discussion of benefits and risks matter." },
	"should-psa-screening-for-prostate-cancer-be-routine-for-every-older-man": { title: "Who may benefit from PSA screening for prostate cancer?", bottomLine: "Some men may benefit, but the trade-off is close. U.S. USPSTF guidance calls for a personal decision at ages 55 to 69 and advises against routine screening from age 70. A small fall in prostate-cancer deaths must be weighed against false alarms, biopsy harms and treatment of cancers that would never cause harm." },
	"do-fda-approved-smoking-cessation-medications-help-adults-quit-smoking": { title: "Do U.S. FDA-approved medicines help adults quit smoking?", bottomLine: "Yes, for adults who smoke and are not pregnant. Nicotine replacement, varenicline and bupropion SR improve quit rates compared with little or no treatment. Behavioral support improves results. Choice of medicine depends on health history, other drugs, side effects, age, cost and personal preference. Pregnancy needs a separate assessment." },
	"does-hiv-cause-aids": { bottomLine: "Yes. AIDS is the most severe stage of HIV infection, when immune damage becomes serious. HIV treatment can suppress the virus and prevent this progression for most people who can access and stay on treatment. Sustained viral suppression also prevents sexual transmission." },
	"does-modern-treatment-cure-hepatitis-c-for-most-people": { bottomLine: "Yes. Modern antiviral medicines cure hepatitis C in more than 95% of people who receive suitable treatment, usually with 8 to 12 weeks of tablets. Testing and access to care remain major barriers. Cure does not prevent a new infection later." },
	"does-treating-high-blood-pressure-reduce-the-risk-of-stroke-and-heart-disease": { bottomLine: "Yes. Treating high blood pressure lowers the risk of stroke, heart attack, heart failure and early death. Treatment can include changes in daily habits and medicines. Benefit depends on starting risk, how much blood pressure falls, side effects and staying on treatment." },
	"do-statins-reduce-heart-attacks-and-strokes-for-people-at-elevated-cardiovascular-risk": { bottomLine: "Yes, for selected adults at higher risk of heart disease or stroke. Statins reduce these events, with larger absolute benefit when starting risk is higher. They are not needed by every low-risk adult. Evidence for starting after age 75 without known heart disease is less certain." },
	"should-adults-take-daily-low-dose-aspirin-to-prevent-a-first-heart-attack-or-stroke": { bottomLine: "Not routinely. U.S. USPSTF guidance finds a small possible net benefit for selected adults aged 40 to 59 with higher heart risk and low bleeding risk. It advises against starting at age 60 or older. This does not apply to aspirin prescribed after a heart attack, stroke, stent or other heart disease." },
	"do-syringe-services-programs-reduce-infection-risk-without-increasing-drug-use": { bottomLine: "Yes. Comprehensive syringe programs lower HIV risk and connect people with testing, treatment and overdose care. Evidence for preventing hepatitis C is less clear for syringe access alone. It is stronger when coverage is high and access is combined with treatment such as methadone or buprenorphine." },
	"do-medications-for-opioid-use-disorder-reduce-overdose-deaths": { bottomLine: "Yes. Methadone and buprenorphine greatly lower overdose and overall death rates while people remain in treatment. This is medical care, not simply swapping one addiction for another. Naltrexone is also U.S. FDA-approved, but evidence about deaths is less consistent and depends on starting and staying on treatment." },
	"is-global-sea-level-rising-and-accelerating-due-to-human-caused-climate-change": { bottomLine: "Yes. Gauges and satellites show that global sea level is rising and the rise has sped up. Human influence has been the main driver since at least 1971, according to the IPCC. Local changes can differ because land moves and ocean currents shift." },
	"is-extreme-heat-becoming-more-frequent-or-intense-because-of-human-caused-climate-change": { bottomLine: "Yes. The IPCC finds it virtually certain that hot extremes have become more frequent and intense across most land since the 1950s. It has high confidence that human-caused warming is the main driver. Local harm also depends on humidity, city heat, exposure and preparedness." },
	"has-human-influence-increased-the-frequency-of-concurrent-heatwaves-and-droughts": { bottomLine: "Yes, globally, with regional differences. The IPCC has high confidence that human influence has made heatwaves and droughts more likely to occur together. That does not make climate change the cause of every drought or fire. It shifts the odds toward hot, dry conditions that can worsen many risks." },
	"has-human-influence-increased-fire-weather-occurrence-in-some-regions": { bottomLine: "Yes, in some regions. The IPCC has medium confidence in this finding. Fire weather means hot, dry and windy conditions that help fires start and spread. Actual damage also depends on fuel, ignition, land use, fire control and the people or buildings exposed." },
	"do-most-people-consume-too-much-sodium-and-does-reducing-sodium-lower-blood-pressure": { title: "Does eating less sodium lower blood pressure?", bottomLine: "Yes. Trials find that cutting sodium lowers blood pressure, with larger average effects in people whose blood pressure starts higher. WHO and U.S. health guidance also report that most people eat more sodium than recommended. Intake patterns and the effect of reducing intake are separate findings." },
	"does-fine-particulate-air-pollution-cause-cardiovascular-disease-and-lung-cancer": { bottomLine: "Yes. Fine particles, especially PM2.5, cause harm to the heart and blood vessels and raise the risk of early death. Outdoor air pollution and these particles also cause lung cancer. Risk is not limited to smokers or visibly dirty air. Lower levels over long periods still matter." },
	"do-portable-hepa-air-cleaners-reduce-indoor-fine-particle-pollution": { bottomLine: "Yes. A suitably sized air cleaner can greatly lower fine particles, including wildfire smoke, in the room where it runs. It needs effective filters, enough airflow and maintenance. It does not remove every pollutant or guarantee symptom relief. It does not replace advice to leave unsafe areas or control pollution sources." },
	"can-indoor-dampness-and-mold-worsen-respiratory-health": { bottomLine: "Yes. Damp or moldy rooms are linked to asthma symptoms, cough, wheeze, allergies and breathing infections. Fixing moisture and removing mold is recommended; waiting to identify the mold species is usually not needed. That does not mean mold explains every symptom in a building." },
	"do-gas-stoves-worsen-indoor-air-quality-and-childhood-asthma-risk": { bottomLine: "Yes for air pollution; the asthma finding is less certain. Gas stoves raise indoor nitrogen dioxide and other pollutants. Studies link gas cooking or indoor nitrogen dioxide to more childhood asthma or wheeze, but the exact causal share is uncertain. Ventilation helps, and electric cooking avoids combustion indoors. Stoves should not be used for heat." },
	"are-transitional-fossils-missing-from-the-fossil-record": { bottomLine: "No. Many fossils show transitions in features, including in whales, birds, mammals and human ancestors. The record has gaps, but it is not missing all these links. Fossils usually show branching histories, not a perfect chain of direct ancestors." },
	"does-regular-cannabis-use-increase-the-risk-of-psychosis-and-schizophrenia-especially-for-adolescents-and-heavy-or-high-thc-users": { bottomLine: "Cannabis use is strongly linked to later psychosis. Risks are highest with frequent use, early starting age and high-THC products. Much of the evidence tracks people rather than assigning cannabis use in trials. It supports a possible causal contribution, not a claim that every user will develop schizophrenia." },
	"does-cannabis-use-impair-driving-and-increase-crash-risk": { bottomLine: "Yes. Recent cannabis or THC use impairs driving skills and is linked to more crashes. Risk varies with dose, timing, product, tolerance and other drugs, especially alcohol. A blood THC level does not measure impairment in the same way as blood alcohol. Do not drive while impaired." },
	"are-antidepressants-effective-for-major-depressive-disorder-and-how-big-is-the-average-benefit": { bottomLine: "Yes, on average, but the benefit is modest and varies. Large trial reviews find that antidepressants work better than placebo for short-term adult major depression. Severity, side effects, therapy options, personal preferences and follow-up matter when choosing treatment." },
	"does-exercise-reduce-symptoms-of-depression": { bottomLine: "Yes. Exercise can reduce depression symptoms and can be a treatment option or an addition to other care. It is not a guaranteed cure. Severe symptoms, physical limits, access and safety can affect what is possible. Therapy, medicine and urgent care may still be needed." },
	"do-later-school-start-times-help-teenagers-get-more-sleep": { bottomLine: "Yes. Later school starts usually help teens sleep longer by better matching their body clocks. Pediatric and sleep groups recommend starting no earlier than 8:30 a.m. Evidence is clearest for sleep. Effects on grades, mood, travel and family schedules depend on how the change is put into practice." },
	"is-cognitive-behavioral-therapy-for-insomnia-a-first-line-treatment-for-chronic-insomnia": { bottomLine: "Yes. CBT-I is the recommended first treatment for long-term adult insomnia when available. It combines structured work on sleep habits, time in bed and thoughts about sleep. It is more than general advice about good sleep. Sleeping pills can still help some people in the short term." },
	"do-probiotics-reliably-treat-depression-or-anxiety": { title: "Can probiotics help treat depression or anxiety?", bottomLine: "They may help as an addition to usual care. Reviews of trials find small to moderate symptom improvements, especially in people with a diagnosis. Results differ by strain, dose, duration and group studied. Probiotics are not established replacements for mental-health treatment." },
	"do-learning-styles-improve-educational-outcomes": { bottomLine: "Evidence does not justify routinely sorting students into fixed visual or auditory learning styles. Some studies find small benefits, but a dependable, lasting classroom benefit is not established. Students can still have preferences and access needs. Teaching should also suit the task being learned." },
	"does-aspartame-cause-cancer-at-typical-intake-levels": { bottomLine: "A cancer risk at typical intake is not established. IARC's possible-cancer classification reflects limited evidence, including a liver-cancer signal. Food-safety bodies still regard intake below their daily limits as acceptable for the general population. Human studies disagree. Hazard classification and risk at a given dose answer different questions." },
	"does-vitamin-d-supplementation-prevent-or-treat-covid-19-beyond-correcting-deficiency": { bottomLine: "Not as a general COVID-19 treatment or prevention strategy. Large trials have not shown meaningful benefit in the general population. Some reviews suggest possible benefits for hospital care, but findings vary and effects on deaths remain uncertain. Treating a real vitamin D deficiency is a separate matter." },
	"do-dietary-supplements-usually-improve-health-in-healthy-adults": { bottomLine: "It depends on the supplement, person and outcome. Routine multivitamins have not established broad protection from heart disease or death in adults without a deficiency. Some trials in older adults find small thinking or memory benefits. Pooled trials suggest a modest fall in cancer cases. Treating a deficiency is a separate question." },
	"do-vitamin-e-or-beta-carotene-supplements-prevent-heart-disease-or-cancer": { bottomLine: "No for routine prevention in adults living in the community who are not pregnant. U.S. USPSTF guidance advises against both for preventing heart disease or cancer. Vitamin E has no net benefit for this purpose. Beta-carotene can cause harm in people at high risk of lung cancer." },
	"is-nuclear-power-more-dangerous-than-fossil-fuel-energy": { bottomLine: "Nuclear power generally causes less routine air pollution and climate harm than fossil-fuel power, especially coal or oil. That does not make it harmless or always the best choice. Accident risks, local health effects and the power source that would replace a plant need separate assessment." },
	"are-commercial-gmo-foods-unsafe-to-eat": { bottomLine: "Evidence does not show that assessed commercial GM foods are inherently more hazardous to eat than comparable ordinary foods. Safety depends on the product, trait and use. This is not a promise of zero risk or a judgment on all future modifications, pesticides or farming practices." },
	"do-polygenic-risk-scores-work-equally-well-across-ancestry-groups": { bottomLine: "No. Scores based mainly on people with European ancestry often predict risk less well in other groups or people with mixed ancestry. More diverse data and new methods are improving this. The gap is not solved. These scores can add useful information for some diseases but are not equally reliable for everyone." },
	"did-asbestos-cause-mesothelioma-and-lung-cancer": { bottomLine: "Yes. Breathing asbestos fibers causes cancer, especially mesothelioma and lung cancer. Mining, manufacture, cutting, sanding and demolition can release fibers. An intact old material and a disturbed material do not necessarily create the same immediate exposure." },
	"did-oral-rehydration-therapy-save-lives-from-diarrheal-disease": { bottomLine: "Yes. Oral rehydration solution replaces water and salts lost through diarrhea and prevents many deaths from dehydration. It must be available and mixed correctly with safe water. Feeding and zinc may also be recommended. Severe or complicated dehydration still needs medical care." },
	"does-communicating-scientific-consensus-change-what-people-believe": { bottomLine: "Often, modestly. Accurate messages about expert agreement can correct mistaken views of what scientists think and slightly shift factual beliefs. They are not enough on their own to persuade everyone. Trust, topic, prior beliefs and message design matter. Changes in belief do not necessarily change behavior or policy preferences." },
	"does-communicating-uncertainty-destroy-public-trust-in-science": { bottomLine: "Usually no. Explaining what is known and what might change can protect trust. Vague caveats, political conflict or weak evidence can still lower confidence. The strongest approach states the specific uncertainty and why it matters to the decision, using numbers where they are supported." },
	"can-correlation-alone-prove-causation": { bottomLine: "No. Two things occurring together can be a clue, not proof that one causes the other. Researchers also check timing, other possible causes, bias and whether findings agree across studies. Experiments or natural experiments can help test the causal explanation." },
	"does-industry-funding-automatically-make-a-study-false": { bottomLine: "No. Industry funding is a reason to check for bias, not proof that a study is false. Funding is linked to more favorable findings in some research fields. The design, comparison, chosen outcomes, missing results and authors' independence all need scrutiny. Disclosing conflicts does not by itself remove them." },
	"does-preregistration-guarantee-a-study-is-trustworthy": { bottomLine: "No. Recording a study plan in advance can reveal selective reporting and separate planned tests from later exploration. But plans can be vague, late, ignored or reported selectively. Trust still depends on the study's design, measures, analysis and clear explanations of changes." },
	"does-sharing-data-and-code-guarantee-a-study-is-reproducible": { bottomLine: "No. Sharing data and code helps others check and rerun a study. Missing files, unclear instructions or unavailable software can still prevent this. Privacy can also limit access. Openness does not repair a weak study design or biased measurements." },
	"is-radiofrequency-radiation-from-phones-and-5g-too-low-energy-to-damage-dna-directly": { bottomLine: "Yes. Individual radio waves from phones, Wi-Fi and 5G lack the energy to break DNA directly in the way ionizing radiation can. This rules out that particular mechanism. It does not, by itself, settle every possible health question about exposure." },
	"does-possibly-carcinogenic-mean-rf-radiation-is-proven-to-cause-cancer": { title: "What does IARC's possible-cancer classification mean for radiofrequency exposure?", bottomLine: "It signals limited evidence or unresolved uncertainty, not proof that ordinary exposure causes cancer. IARC's classification concerns whether an agent could cause harm. It does not directly estimate the risk from everyday phone use." },
	"is-hearing-loss-linked-to-higher-dementia-risk-and-can-hearing-aids-help": { title: "Can hearing aids slow cognitive decline?", bottomLine: "They may help some older adults at higher starting risk. A trial found benefit in a higher-risk group, not across everyone studied. Hearing loss is linked to dementia, but hearing aids are not a guaranteed way to prevent it. Treating hearing loss also helps communication and daily life." },
	"are-parent-training-and-behavioral-therapy-effective-parts-of-adhd-treatment": { bottomLine: "Yes. Parent training is recommended first for young children with ADHD and can help families with older children too. Evidence is strongest for parenting skills, disruptive behavior and family life. Effects on core ADHD symptoms are less clear. Treatment should suit the child's age and needs." },
	"are-pfas-exposures-linked-to-higher-cholesterol-and-reduced-vaccine-antibody-response": { bottomLine: "Yes. These are among the better-supported health findings for several PFAS chemicals. Studies link exposure to higher cholesterol and lower antibody responses to vaccines. Average effects are usually modest and differ by chemical, age, vaccine and exposure history. A group-level association cannot predict an individual's illness." },
	"should-individuals-get-pfas-blood-testing-and-does-it-change-medical-care": { title: "When can PFAS blood testing be useful?", bottomLine: "It can help people with likely high exposure, especially if results guide ways to reduce exposure or plan follow-up. It is not routine screening for everyone. It cannot identify the source, diagnose illness or predict a person's future health. There is no approved medical treatment to remove PFAS from the body." },
	"are-microplastics-in-drinking-water-proven-to-cause-human-health-harms-at-current-exposure-levels": { title: "What is known about health risks from microplastics in drinking water?", bottomLine: "Particles are found in tap and bottled water, but harm to people at these levels is not established. That does not prove safety. Evidence is incomplete about smaller particles, additives and long-term exposure. Better measurement and health studies are needed alongside efforts to reduce plastic pollution." },
	"are-ultra-processed-foods-linked-to-worse-health-outcomes-and-how-much-is-causation-versus-confounding": { bottomLine: "Yes. Higher intake is linked to obesity, heart and metabolic disease, some mental-health problems and earlier death. Most studies observe diets rather than assign them. They cannot cleanly separate processing from calories, food quality, texture, cost and other factors. The category also includes very different foods." },
	"are-intensive-behavioral-interventions-effective-for-children-with-obesity-and-does-dose-matter": { title: "Do intensive behavioral programs help children with high BMI?", bottomLine: "Yes. Structured programs involving the family can improve weight-related outcomes. U.S. USPSTF guidance highlights 26 or more contact hours for benefit. These programs combine several kinds of support, not just advice to try harder. Access can be difficult." },
	"is-obesity-a-major-health-risk-condition-at-the-population-level": { bottomLine: "Yes. Across populations, obesity is linked to higher risks of diabetes, heart disease, several cancers and early death. BMI does not perfectly describe one person's health. Fitness, fat distribution, medicines, disability and social conditions matter too. Risk information should not be used to shame people." },
	"do-glp-1-based-medications-produce-meaningful-weight-loss-for-adults-with-obesity": { bottomLine: "Yes. Medicines such as semaglutide and tirzepatide produce meaningful average weight loss in trials of eligible adults. They need medical supervision. Side effects, other health conditions, cost and access matter. So do nutrition, activity, muscle preservation and how weight loss is maintained over time." },
	"do-covid-19-vaccines-cause-menstrual-cycle-changes-and-are-the-changes-temporary": { title: "How can COVID-19 vaccination affect menstrual cycles?", bottomLine: "Some people have small, temporary changes in cycle length, flow or symptoms. The best-tracked studies find an average change of about a day or less after one dose in a cycle. Two doses in the same cycle can produce larger temporary changes. This is not evidence of infertility." },
	"can-covid-19-cause-long-term-symptoms-even-after-mild-infection": { bottomLine: "Yes. Long COVID can follow an infection that never required hospital care. Risk varies with age, sex, variant, vaccination, repeat infections and the severity of the first illness. Studies also measure it differently. There is still no single cure." },
	"is-higher-potassium-intake-from-food-recommended-to-reduce-blood-pressure-and-cardiovascular-risk": { bottomLine: "Yes, for most adults. Guidelines favor more potassium-rich foods, such as fruit, vegetables, beans and nuts, especially when sodium intake is high. People with kidney disease or medicines that affect potassium need clinical advice first. Food-based guidance is not a recommendation for everyone to take potassium supplements." },
	"do-potassium-enriched-salt-substitutes-reduce-blood-pressure-compared-with-regular-salt": { bottomLine: "Yes. Lower-sodium salt with added potassium lowers blood pressure. Some trials in higher-risk groups also find fewer strokes or deaths. WHO's recommendation is conditional and does not cover everyone. It excludes children, pregnant people and people with kidney impairment or other conditions or medicines that make extra potassium dangerous." },
	"is-psilocybin-assisted-therapy-an-established-treatment-for-depression": { bottomLine: "Not yet as routine care. Supervised treatment has shown promising short-term effects in trials. It remains unclear how long benefits last and how much expectations affect the results. Safety, patient selection, support and confirmation in larger trials remain important questions." },
	"is-intermittent-fasting-better-than-daily-calorie-restriction-for-weight-loss": { bottomLine: "Not generally. Fasting plans can help some adults lose weight, especially by reducing total calories. Trials usually find similar average weight loss to cutting calories each day. Some people find a particular schedule easier to follow. Evidence does not support a special shortcut that works for everyone." },
	"is-social-media-proven-to-be-the-main-cause-of-worsening-teen-mental-health": { title: "How is social media use linked to teen mental health?", bottomLine: "Harassment, disrupted sleep, social comparison and some heavy-use patterns are linked to worse outcomes. It remains unclear how much social media drives the wider rise in teen mental-health problems. Effects vary, and many studies cannot separate cause from consequence. Concern is warranted without treating it as a single settled cause." },
	"do-graduated-driver-licensing-laws-reduce-teen-driver-crashes-and-deaths": { bottomLine: "Yes, especially for the youngest new drivers. Programs phase in driving freedom, starting with supervision and limits on high-risk situations such as night driving and teen passengers. Stronger programs tend to work better. Benefits are smaller or less certain for older new drivers and depend on the law's details." },
	"does-homeopathy-reliably-work-beyond-placebo-for-treating-health-conditions": { title: "Does homeopathy work beyond placebo for health conditions?", bottomLine: "Major reviews do not find dependable benefit beyond effects compatible with placebo. Positive findings in some small trials weaken when bias and better-quality evidence are considered. Homeopathy should not replace treatments known to work, especially for serious or urgent conditions." },
	"does-ivermectin-reliably-improve-covid-19-outcomes": { title: "Does ivermectin improve COVID-19 outcomes?", bottomLine: "A reliable benefit for important COVID-19 outcomes has not been shown. Larger, better-controlled trials and later reviews do not support its use for COVID-19 outside proper trials. Early positive findings were fragile and vulnerable to bias." },
	"does-creatine-monohydrate-improve-strength-training-and-is-it-generally-safe": { title: "Does creatine improve strength-training results?", bottomLine: "Yes, modestly. Creatine monohydrate can improve strength or lean-mass gains with resistance training and repeated high-intensity effort. It is generally well tolerated at usual doses in healthy people. That is a separate safety finding, not proof of safety for everyone or a general endurance benefit." },
	"can-direct-to-consumer-genetic-tests-reliably-predict-most-common-diseases": { title: "What can consumer genetic tests tell you about common-disease risk?", bottomLine: "They can offer some risk clues, not a diagnosis or destiny. Common diseases involve many genes as well as environment and behavior. Results can be less accurate for ancestries poorly represented in the data. Medical decisions need suitable clinical confirmation and support." },
	"can-planting-trees-alone-solve-climate-change": { title: "How much can protecting and planting trees help the climate?", bottomLine: "Forests can help, but they cannot replace rapid cuts in fossil-fuel emissions. Benefits depend on where and what is planted, water, fire, biodiversity and how long extra carbon stays stored. Changes in how much sunlight the land reflects also matter." },
	"can-crispr-based-gene-therapy-treat-sickle-cell-disease-in-eligible-patients": { bottomLine: "Yes, for selected patients in specialist care. U.S. FDA-approved CRISPR therapy can greatly reduce severe sickle-cell pain crises. It is intensive treatment, not a simple outpatient cure. Serious treatment risks and long-term follow-up need specialist assessment." },
	"can-a-noninvasive-prenatal-screening-test-diagnose-fetal-chromosomal-conditions-by-itself": { bottomLine: "No. A blood-based prenatal screen can be very sensitive for common chromosome conditions, but screening is not diagnosis. A positive result needs counseling and a diagnostic test before irreversible pregnancy or medical decisions." },
	"can-fda-approved-rpe65-gene-therapy-improve-vision-related-function-in-a-rare-inherited-retinal-disease": { title: "Can U.S. FDA-approved RPE65 gene therapy improve vision?", bottomLine: "Yes, for some people with the specific inherited retinal disease it treats. Luxturna requires confirmed disease-causing changes in both RPE65 copies and enough living retinal cells. It can improve useful vision. It is not a cure for blindness or a treatment for most inherited eye diseases." },
	"does-a-mediterranean-style-diet-reduce-cardiovascular-events-in-high-risk-adults": { bottomLine: "Yes. Trials support fewer major heart and blood-vessel events in higher-risk adults following this eating pattern, especially instead of a poorer diet. The evidence concerns the whole pattern. It does not show that one food, or wine on its own, provides the same benefit." },
	"do-mindfulness-meditation-programs-reduce-anxiety-or-depression-symptoms": { bottomLine: "Some programs help some people, usually modestly. Average anxiety or depression symptoms can improve, but results differ. Meditation is not a substitute for urgent mental-health care or established treatment when symptoms are severe." },
	"can-smn-gene-therapy-improve-outcomes-for-some-children-with-spinal-muscular-atrophy": { bottomLine: "Yes, for eligible children, especially with early treatment. Onasemnogene abeparvovec can improve survival and movement milestones. It is not a universal cure. Disease type, starting function, genetic factors and liver safety matter, and long-term follow-up is needed." },
	"can-car-t-cell-therapy-produce-durable-remissions-for-some-blood-cancers": { bottomLine: "Yes, for some eligible patients whose specific blood cancers have returned or resisted treatment. CAR T-cell therapy can produce deep, lasting remissions, not a guaranteed cure. Serious risks include severe immune reactions, nervous-system harm, low blood-cell counts, infections and rare new T-cell cancers." },
	"do-omega-3-fish-oil-supplements-broadly-prevent-first-heart-attacks-or-strokes": { bottomLine: "Not as a general claim for healthy adults. These supplements lower blood fats called triglycerides, and some trials suggest small heart benefits. Large prevention studies do not show clear reductions in major heart events or stroke for everyone. Eating fish and using prescription products for selected patients are separate questions." },
	"are-ketogenic-diets-a-proven-superior-long-term-weight-loss-strategy-for-most-adults": { title: "How do ketogenic diets compare with other weight-loss diets over time?", bottomLine: "They can help people lose weight, especially at first. Their long-term advantage over other calorie-reducing diets is usually modest. Keeping to the diet can be hard. Cholesterol, kidney disease, medicines, pregnancy and eating disorders can change the balance of benefit and risk." },
	"does-melatonin-reliably-treat-chronic-insomnia-in-adults": { title: "How well does melatonin treat chronic insomnia in adults?", bottomLine: "Evidence is mixed, with small benefits for falling asleep in some studies. Melatonin has a clearer role in body-clock problems such as jet lag or delayed sleep timing. Product quality varies. CBT-I is the better-established first treatment for chronic insomnia." },
	"do-routine-childhood-vaccines-overwhelm-or-weaken-the-immune-system": { bottomLine: "No. The routine schedule does not overwhelm or weaken a healthy child's immune system. Children meet many more antigens in everyday life. Studies do not find that greater early vaccine-antigen exposure leads to more unrelated infections later. Some children still have medical reasons to avoid particular vaccines." },
	"does-psychotherapy-help-adults-with-depression": { bottomLine: "Yes. Several structured talking therapies reduce depression symptoms and improve the chance of recovery compared with usual care or control groups. Not everyone benefits equally. Choice depends on severity, preferences, access, past response and safety needs." },
	"are-unapproved-stem-cell-treatments-proven-safe-and-effective-for-most-advertised-conditions": { title: "What evidence supports commercially advertised unapproved stem-cell treatments?", bottomLine: "Clinics advertise many uses without adequate evidence of safety or benefit. Proven stem-cell treatments exist for a limited set of blood and immune disorders. Other uses can be studied in regulated trials. Neither fact validates a commercial cure-all." },
	"are-multicancer-early-detection-blood-tests-proven-to-reduce-cancer-deaths-in-average-risk-people": { title: "Do multicancer blood screening tests reduce cancer deaths?", bottomLine: "The evidence cited here does not establish that screening healthy, average-risk people lowers cancer deaths. Detecting a cancer signal is not the same outcome. False alarms, missed cancers, finding cancers that would never cause harm, and follow-up procedures all affect the balance of benefits and harms." },
	"can-consumer-microbiome-tests-reliably-diagnose-disease-or-prescribe-personalized-diets": { title: "Can consumer microbiome tests guide a diagnosis or personal diet?", bottomLine: "Not reliably at present. Gut microbes matter, but consumer stool tests lack agreed healthy ranges and proven links from results to useful treatment or diet choices. Sampling and analysis also vary. Providers can give quite different profiles from the same material." },
	"can-recovered-memory-techniques-reliably-reveal-accurate-hidden-trauma-memories": { title: "Can a recovered-memory technique establish that a memory is accurate?", bottomLine: "No. Real trauma can be remembered after a period without thinking about it. But suggestion, hypnosis, guided imagery and pressure can also create confident false memories. A memory's vividness or the person's confidence does not verify it. Independent supporting evidence is the key safeguard." },
	"do-non-sugar-sweeteners-reliably-help-with-long-term-weight-control": { title: "How do non-sugar sweeteners affect weight over time?", bottomLine: "Replacing sugary products can cut calories and modestly help weight in some short trials. A lasting benefit across populations is not established. Effects depend on what the sweetener replaces and whether people eat more elsewhere. Short-term substitution and long-term weight control are different questions." },
	"does-induced-abortion-increase-breast-cancer-risk": { bottomLine: "No. Better-quality studies following people over time do not find a rise in breast-cancer risk after induced abortion. Earlier positive reports often relied on people recalling or disclosing past abortions after a cancer diagnosis. Differences in reporting can bias that comparison." },
	"does-bariatric-surgery-reduce-mortality-and-major-cardiovascular-risk-in-severe-obesity": { bottomLine: "Probably yes for selected adults with severe obesity. Large long-term studies link surgery to fewer deaths and major heart or blood-vessel events than non-surgical care. Most did not assign treatment at random, so the exact causal benefit is less certain. Surgery has risks and requires lifelong nutrition and follow-up care." },
	"do-long-term-opioids-provide-sustained-benefit-for-chronic-non-cancer-pain": { bottomLine: "For most chronic non-cancer pain, a large lasting advantage over other care is not established. Overdose, dependence, falls and other harms rise with dose and exposure. Some selected patients benefit. Use needs clear goals and review, not automatic dose increases. This is not advice to stop existing treatment abruptly." },
	"should-menopausal-hormone-therapy-be-used-to-prevent-chronic-disease-in-most-postmenopausal-adults": { bottomLine: "No, not routinely for prevention in people without symptoms. Trials find both benefits and harms, which differ by medicine, age and timing. The overall balance does not support starting systemic hormones mainly to prevent heart disease, dementia or other chronic illness. Treating troublesome menopause symptoms is a separate question." },
	"does-evolution-have-a-predetermined-goal-or-always-produce-perfect-organisms": { title: "Does evolution have a predetermined goal?", bottomLine: "No goal has been scientifically detected. Evolution also does not produce perfect organisms. Inherited changes, selection, chance and migration act within limits set by history and the environment. Adaptations involve trade-offs, not a fresh design optimized from scratch." },
	"are-socially-defined-human-racial-groups-discrete-biological-subspecies": { bottomLine: "No. Human genetic variation is real, but it overlaps across groups and changes with ancestry and geography. Socially defined races are not separate biological subspecies. Race still has powerful social effects, and racism has real consequences for health." },
	"does-the-newborn-vitamin-k-injection-prevent-dangerous-bleeding-and-is-it-safe": { title: "Does vitamin K at birth prevent dangerous bleeding?", bottomLine: "Yes. The injection is highly effective against bleeding caused by vitamin K deficiency. This can include bleeding in the brain or gut without warning. Serious harms from the injection are very rare. The separate claim that it causes childhood cancer has not held up in later studies." },
	"does-fecal-microbiota-transplantation-work-for-recurrent-c-difficile-infection": { bottomLine: "Yes, for selected patients whose C. difficile infection returns after antibiotics. Carefully screened microbiota-based treatment improves the chance of lasting recovery. It carries infection risks and needs regulated clinical care. It is not a general gut cleanse or a proven treatment for unrelated conditions." },
	"do-simple-febrile-seizures-usually-cause-brain-damage-or-lasting-developmental-problems": { bottomLine: "Usually no. A brief simple seizure with fever does not usually cause lasting brain or developmental harm. Seizures can recur, and later epilepsy risk is modestly higher, but that does not prove the brief seizure damaged the brain. Long, repeated, one-sided or otherwise unusual seizures need a separate assessment." },
	"do-routine-general-health-checks-reduce-deaths-in-otherwise-healthy-adults": { bottomLine: "Trials do not find fewer deaths from broad, untargeted check-up packages for otherwise healthy adults. This does not argue against primary care, recommended vaccines or screening. Tests for symptoms and follow-up of known risks are different from testing everyone for many conditions without a specific reason." },
	"does-thawing-permafrost-amplify-warming-and-does-it-make-runaway-warming-inevitable": { title: "How does thawing permafrost add to global warming?", bottomLine: "Thawing ground releases carbon dioxide and methane, which add more warming. Some effects last beyond human timescales. Evidence does not support a single near-term switch to unstoppable warming. Faster emissions cuts still limit thaw and the amount of carbon released." },
	"do-vitamin-d-supplements-prevent-fractures-or-falls-in-generally-healthy-adults": { bottomLine: "Not in large trials of generally healthy adults living in the community. Routine supplements have not reduced falls or fractures in people not selected for deficiency or osteoporosis. Treating a measured deficiency, osteoporosis or problems absorbing nutrients is a different question." },
	"can-polygraph-tests-reliably-detect-lies": { title: "How accurately do polygraph tests detect lies?", bottomLine: "They measure bodily arousal, not lying itself. Some specific-event tests perform better than chance in research, but errors, examiner judgment and countermeasures limit accuracy. A result cannot prove someone lied. Broad employee or security screening is especially vulnerable to falsely labeling truthful people." },
	"do-commercial-brain-training-games-produce-broad-lasting-cognitive-improvements": { bottomLine: "People improve at the game they practice and sometimes at similar tasks. Evidence for lasting gains in everyday thinking, memory or school performance is weak and inconsistent. Preventing dementia is not established. Results from structured research programs do not validate every commercial app." },
	"is-sexual-orientation-conversion-therapy-effective-and-safe": { bottomLine: "Credible evidence does not show that conversion efforts reliably change sexual orientation. Reviews find risks including shame, depression, anxiety, damaged relationships and suicidal thoughts or behavior. Supportive counseling without a fixed goal of changing orientation is different." },
	"does-private-umbilical-cord-blood-banking-benefit-most-families": { bottomLine: "Most families are unlikely to benefit from routine private storage. Professional bodies favor public donation where available. Directed family storage can help when a close relative has a condition treatable by cord-blood transplant. Broad claims about future regenerative uses go beyond proven care." },
	"does-pgt-a-improve-cumulative-live-birth-rates-for-most-ivf-patients": { bottomLine: "Routine embryo chromosome screening has not been shown to increase the total chance of live birth for most IVF patients. It may reduce miscarriages or the time to pregnancy in selected groups. Results depend on age, embryo number, test accuracy and how uncertain findings are handled. Counting all embryos matters." },
	"are-polygenic-embryo-screening-scores-clinically-proven-to-improve-childrens-health": { title: "Does polygenic embryo screening improve children's health?", bottomLine: "The cited evidence does not establish a clinical benefit. Risk scores predict some group-level differences, but choosing among a few sibling embryos is harder. Ancestry and future environments affect accuracy. Lowering one predicted risk can shift another. Professional bodies do not support routine use on this evidence." },
	"can-blood-based-tumor-dna-testing-replace-tissue-biopsy-for-most-cancers": { bottomLine: "Not for most cancers. Blood tests can reveal useful genetic changes or help track some tumors. They can help when tissue is unsafe or insufficient. A negative result can still miss cancer that releases little DNA. Tissue usually remains necessary to identify the cancer and its structure." },
	"does-secure-firearm-storage-reduce-youth-firearm-injury-and-suicide": { bottomLine: "Homes with firearms locked, unloaded and out of children's reach have lower rates of youth firearm suicide and accidental injury. Most evidence observes households rather than assigns storage methods in trials. Findings are consistent, and combining storage practices provides stronger protection. Restricting immediate access is the likely mechanism." },
	"do-smoke-free-indoor-laws-reduce-heart-attacks-and-other-cardiovascular-events": { bottomLine: "Yes. Strong indoor smoking bans reduce smoke exposure and are followed by fewer heart attacks and related events. Most studies compare real policy changes rather than assign laws at random. Their timing, consistent findings and larger effects with stronger bans support a causal benefit." },
	"does-making-a-student-repeat-a-grade-reliably-improve-long-term-outcomes": { title: "How does repeating a school grade affect later outcomes?", bottomLine: "Repeating a grade does not reliably improve long-term learning or social outcomes and can raise dropout risk. Some students make short-term gains. Individual needs matter, but repeating the same teaching without different support is generally a weak substitute for targeted help." },
	"does-high-quality-preschool-improve-later-educational-outcomes": { bottomLine: "Good preschool improves school readiness and can help later learning and social outcomes, especially for disadvantaged children. Early test-score gains often shrink once other children enter school. Some longer-term benefits persist. Quality, time in the program, other care options and later schooling all matter." },
	"does-giving-every-student-a-laptop-reliably-improve-learning": { title: "When do one-to-one school laptops improve learning?", bottomLine: "They improve access, but average gains in school achievement are modest and inconsistent. Benefits depend on teaching, curriculum, support, home access and how devices are used. Writing and feedback can improve. Adding distraction instead of useful practice can undermine the goal." },
	"does-formative-assessment-improve-k12-learning": { bottomLine: "It can, when teachers check understanding and adapt teaching while students still have time to improve. More tests or scores alone do not provide that benefit. Useful feedback and action by teachers and students matter. Effects vary by subject, design and how the approach is used." },
	"does-alcohol-improve-sleep-when-used-as-a-nightcap": { bottomLine: "No overall. Alcohol may help someone fall asleep faster but can reduce REM sleep and disrupt sleep later in the night. Higher doses make this worse. It can also worsen snoring and sleep apnea. It is not an established treatment for insomnia." },
	"does-long-term-night-shift-work-increase-chronic-health-risks": { bottomLine: "Long-term night or rotating shifts are linked to disrupted sleep, heart and metabolic disease, and some mental-health and safety problems. IARC classifies night-shift work as probably cancer-causing. Exact personal risks and causal effects remain uncertain because work patterns, duration and other habits differ." },
	"does-white-noise-reliably-improve-sleep": { title: "Can white noise improve sleep?", bottomLine: "It helps some people by masking changing background sounds. Overall evidence is low quality and inconsistent. It can also add unwanted noise. Benefit depends on the setting; white noise does not automatically improve sleep." },
	"do-weighted-blankets-reliably-treat-insomnia-or-anxiety": { title: "How much do weighted blankets help sleep or anxiety?", bottomLine: "Some trials find better reported sleep or less anxiety in selected groups. Measured effects and results across groups are inconsistent, so a general treatment benefit is not established. They should not replace proven care. They can be unsafe for someone who cannot remove the blanket unaided." },
	"is-mouth-taping-a-proven-safe-treatment-for-snoring-or-sleep-apnea": { title: "Does mouth taping help snoring or sleep apnea safely?", bottomLine: "A safe, general treatment benefit is not established. Studies are small and limited to selected people. Taping can be risky with blocked nasal breathing, vomiting risk or unrecognized sleep apnea. Snoring or suspected apnea needs assessment, not simply forcing the mouth closed." },
	"do-magnesium-supplements-reliably-improve-insomnia": { title: "Do magnesium supplements help insomnia?", bottomLine: "Small trials in older adults suggest possible modest benefits, but the evidence is weak and inconsistent. A meaningful benefit for the general population is not established. Treating a true deficiency is different. Supplements can cause diarrhea and can be unsafe with kidney disease or some medicines." },
	"is-cannabis-an-established-treatment-for-chronic-insomnia": { bottomLine: "No. Some people sleep better, especially when another condition such as pain improves. Insomnia trials are few, short and varied. Tolerance, dependence, next-day impairment and rebound sleep problems limit long-term use. Products and mental-health risks also differ." },
	"are-sedating-antihistamines-good-regular-treatments-for-chronic-insomnia": { bottomLine: "No. Medicines such as diphenhydramine cause short-term drowsiness, but lasting insomnia benefit is poorly supported. Tolerance, next-day effects and other side effects matter, especially in older adults. Guidelines favor CBT-I and advise against routine diphenhydramine for chronic insomnia." },
	"does-static-stretching-before-exercise-prevent-injuries": { bottomLine: "Stretching alone does not consistently prevent all exercise injuries. It may help prevent some muscle or tendon injuries as part of regular preparation. It helps less with joint, impact or overuse injuries. Strength, gradual increases in load and a suitable warm-up matter too." },
	"is-creatine-monohydrate-effective-and-generally-safe-for-healthy-adults": { bottomLine: "Creatine monohydrate improves high-intensity exercise and can add strength and lean mass with training. Studied doses are generally safe for healthy adults; temporary water-weight gain is common. This does not validate every product or medical claim. Kidney disease and other relevant conditions need clinical advice." },
	"does-recreational-running-cause-knee-or-hip-osteoarthritis": { bottomLine: "Ordinary recreational running has not been shown to cause knee or hip arthritis. Studies often find similar or lower rates than with inactivity. Very high competitive loads, past injury, age, weight and joint structure can change personal risk. Persistent pain or changed movement still needs assessment." },
	"does-cardio-cancel-muscle-gains-from-strength-training": { bottomLine: "Usually no. Combining cardio and strength training can improve both. Updated reviews find little average loss of muscle growth or maximum strength. Very high endurance loads, poor recovery and the order of exercise can create trade-offs. Explosive power may be more affected." },
	"can-regular-ice-baths-after-lifting-blunt-muscle-growth": { bottomLine: "Probably, if used right after most lifting sessions. Cold-water immersion can reduce soreness and help short-term recovery, but repeated use after lifting appears to modestly reduce muscle growth. An occasional ice bath is not expected to erase progress." },
	"do-police-body-worn-cameras-consistently-reduce-use-of-force-and-complaints": { bottomLine: "They do not consistently reduce force or most behavior across studies. Complaints often fall, but this can reflect changes in conduct, reporting or resolution. Rules for activation, oversight, access and disclosure matter. Recording events is not the same as ensuring accountability." },
	"is-eyewitness-confidence-a-reliable-measure-of-identification-accuracy": { bottomLine: "Confidence is useful when recorded straight after a fair identification without leading cues. Later feedback, repetition or preparation can inflate it. High confidence later is not a guarantee of accuracy. Both the original viewing conditions and the identification process matter." },
	"do-adult-drug-courts-reduce-reoffending": { bottomLine: "They usually reduce repeat offending modestly compared with ordinary court processing. Results vary, and differences in who enters the programs weaken some evidence. Treatment quality, sanctions, completion rules and what happens to people who do not finish all affect the outcome." },
	"do-face-to-face-restorative-justice-conferences-reduce-repeat-offending-and-help-victims": { title: "How effective are restorative justice conferences?", bottomLine: "Structured meetings with willing victims and offenders can modestly reduce repeat offending and improve victims' satisfaction or recovery. They do not suit every case. Participation must be informed and voluntary, with skilled safeguards. This is different from pressuring someone to forgive." },
	"does-public-area-cctv-reduce-crime": { bottomLine: "Cameras produce a modest average fall in crime, most clearly in parking areas and alongside other measures. Benefits are smaller or inconsistent on many open streets and for violent crime. Crime reduction does not, by itself, settle privacy, bias or accountability concerns." },
	"does-pretrial-detention-influence-later-case-and-life-outcomes": { bottomLine: "Yes. Stronger studies find that detention before trial increases guilty pleas or convictions and can reduce later employment. Effects on future crime are mixed. Simply comparing detained and released people is misleading because the groups differ. Studies using judge assignment or policy changes help separate these effects." },
	"does-solitary-confinement-harm-mental-health": { bottomLine: "Yes. Long periods of isolation are linked to distress, anxiety, depression, self-harm and other mental-health problems. People with existing mental illness face particular danger. Exact causal effects are hard to measure because placement is not random. Different kinds of evidence nevertheless support harm." },
	"does-transgenerational-epigenetic-inheritance-overturn-modern-evolutionary-theory": { bottomLine: "No. Some inherited changes in gene activity affect traits, especially in plants and some animals. These findings extend evolutionary genetics rather than replace it. In mammals, many marks are reset between generations. Strong evidence across several unexposed human generations is scarce." },
	"do-anti-amyloid-drugs-provide-a-clinically-meaningful-net-benefit-in-early-alzheimers-disease": { bottomLine: "Lecanemab and donanemab modestly slow average decline over about 18 months in selected people with early Alzheimer's symptoms. They also remove amyloid. Whether the slowing matters enough to a patient to outweigh infusions, monitoring, cost and brain swelling or bleeding remains a clinical judgment." },
	"does-ai-assisted-mammography-improve-screening-outcomes-beyond-detection-and-workload": { bottomLine: "AI-assisted reading can reduce staff workload and detect more cancers without a large short-term rise in false alarms in the cited studies. That does not establish fewer breast-cancer deaths. Longer follow-up and testing elsewhere are needed to assess missed cancers, unnecessary diagnosis, bias and other harms." },
	"can-direct-air-capture-deliver-affordable-large-scale-carbon-removal": { bottomLine: "Plants can remove carbon dioxide from air, but affordable removal at climate scale is not established. Net benefit needs low-carbon energy, full accounting and durable storage. Cost, materials, water and construction speed remain barriers. It can complement emissions cuts, not replace them." },
	"is-cultivated-meat-clearly-lower-impact-at-commercial-scale": { bottomLine: "Not yet on the evidence cited here. Cultivated meat could use less land, but its large-scale energy and climate footprint is uncertain. Assessments rely on future production assumptions and give very different results. Electricity, materials and factory design can change the comparison with ordinary meat." },
	"is-stratospheric-aerosol-injection-a-proven-safe-climate-solution": { title: "What are the potential benefits and risks of stratospheric aerosol injection?", bottomLine: "Models suggest it could cool average global temperature, but deployment safety is not established. It would not remove carbon dioxide or stop ocean acidification. Rainfall, ozone, ecosystems, unequal impacts and governance pose major risks. Abruptly stopping could cause rapid warming." },
	"are-gene-drive-mosquitoes-proven-safe-and-effective-for-malaria-control-at-population-scale": { title: "What remains uncertain about gene-drive mosquitoes for malaria control?", bottomLine: "Contained research shows potential, but the cited evidence does not establish safe, effective malaria control through open population-scale use. Resistance, ecological effects, spread across borders, reversibility, monitoring and community consent remain unresolved. Promising research is not proof of safe public deployment." },
	"is-the-hot-big-bang-the-best-supported-broad-model-of-cosmic-history": { bottomLine: "Yes. Expansion, ancient background radiation, light elements and the growth of cosmic structure support a much hotter, denser early universe. The model does not by itself explain an absolute beginning, what came before the earliest testable era, or how inflation worked." },
	"has-life-beyond-earth-been-scientifically-confirmed": { bottomLine: "No, as of the evidence review recorded here. Possible habitats and intriguing chemical signals make the search worthwhile, but they are not confirmed life. A convincing finding needs independent measurements and careful checks for explanations that do not involve life." },
	"do-uap-reports-establish-extraterrestrial-visitation": { bottomLine: "No. Some reports remain unidentified because the observations are limited or poor. Publicly available, scientifically validated evidence does not establish alien craft or visits. An unresolved sighting means there is not enough evidence to identify it, not positive evidence of aliens." },
	"does-breaking-habitat-into-smaller-isolated-patches-harm-biodiversity": { bottomLine: "Habitat loss, isolation and more exposed edges usually harm many species. Dividing the same total habitat area into more patches is a separate question: effects can be positive, negative or neutral. Species' movement, habitat quality and scale matter. Habitat loss is the clearest general threat." },
	"do-pollinator-declines-threaten-crop-production": { bottomLine: "Yes, especially for fruit, vegetables, nuts and seeds. Fewer or less diverse pollinators can lower yields and food quality. Most global calories come from crops pollinated by wind or themselves. The threat is therefore not equal across all foods; dietary variety and nutrition are especially exposed." },
	"can-short-duration-batteries-by-themselves-cover-every-grid-reliability-need": { title: "What can short-duration batteries do for electricity-grid reliability?", bottomLine: "They are useful for fast response, reserves and moving electricity across hours. Grids also need ways to handle longer shortages, seasonal changes, network limits and extreme events. Some need resources to restart after a blackout. The right mix depends on the system." },
	"is-green-hydrogen-the-most-efficient-choice-for-every-energy-use": { title: "Where is green hydrogen useful compared with direct electrification?", bottomLine: "Using electricity directly is usually more efficient where practical. Making, moving and converting hydrogen adds energy losses. Low-emission hydrogen may still help with fertilizer, some industrial processes, shipping fuels and long-duration storage." },
	"does-no-till-farming-reliably-store-large-amounts-of-additional-soil-carbon": { title: "How does no-till farming affect soil carbon?", bottomLine: "It often increases carbon near the surface, but deeper sampling can show smaller gains across the full soil profile. Some carbon is redistributed rather than added. No-till can still reduce erosion and improve soil structure. Climate benefit also depends on yields, other emissions and how long carbon remains stored." },
	"do-cover-crops-improve-soil-and-reduce-nitrate-losses-without-always-increasing-yields": { title: "How do cover crops affect soil, nitrate loss and yields?", bottomLine: "They commonly reduce erosion and nitrate loss and can improve soil organic matter and weed control. The next cash crop can yield more, less or about the same. Species, water, nutrients, weather and management determine the result. Environmental benefit does not guarantee a yield increase." },
	"is-regenerative-agriculture-one-standardized-uniformly-proven-farming-system": { title: "What does evidence show about regenerative agriculture?", bottomLine: "The label has no single agreed definition or required set of practices. Practices such as crop rotation, cover crops and agroforestry have evidence, but their effects differ by place and method. The label alone does not establish an outcome. Individual practices and local systems need assessment." },
	"does-overfishing-deplete-fish-stocks-and-can-effective-management-rebuild-them": { title: "Can fisheries management rebuild depleted fish stocks?", bottomLine: "Yes. Catch limits, monitoring, enforcement and habitat or bycatch protection have rebuilt many stocks. Fishing faster than fish can reproduce depletes them. Recovery can be slow, and climate change or weak governance can block it. The benefit depends on effective management, not a rule on paper alone." },
	"is-deep-sea-mining-environmentally-harmless": { title: "What environmental risks does deep-sea mining pose?", bottomLine: "Removing minerals destroys seafloor habitat and creates sediment, noise, light and waste disturbance. Many affected ecosystems recover slowly. The full regional and long-term harm is uncertain because large-scale evidence is limited. Uncertainty about the size of harm is not evidence that mining is harmless." },
	"does-rent-control-help-covered-tenants-without-affecting-housing-supply-or-mobility": { title: "What are the benefits and trade-offs of rent control?", bottomLine: "Covered tenants can gain lower rents and less displacement. Studies also find less moving, conversion away from rental housing and, in some designs, less maintenance or building. Rents outside the controls can rise. The policy's design and local housing shortage strongly affect the trade-off." },
	"does-immigration-substantially-lower-wages-and-employment-for-native-born-workers-overall": { bottomLine: "Average long-run effects on native-born workers' wages and jobs are generally small. Immigration adds labor but also demand, investment and businesses. Some similarly skilled workers, earlier immigrants or places can face different effects. Short-term adjustment can differ from the overall long-run result." },
	"does-the-earned-income-tax-credit-reduce-poverty-and-increase-employment": { title: "Does the U.S. earned income tax credit reduce poverty and increase employment?", bottomLine: "Yes, especially for single parents. The credit raises workers' after-tax income, reduces poverty and has increased entry into work. Effects on hours for people already working are smaller or mixed. As the credit phases out, some second earners face weaker incentives to work." },
	"does-statistical-significance-tell-you-whether-an-effect-is-large-or-important": { bottomLine: "No. A small p-value does not measure an effect's size, its practical value or the chance a claim is true. It describes how unusual the data are under a specified model. Effect size, uncertainty, starting risk, costs and consequences need separate assessment." },
	"does-randomization-automatically-answer-every-causal-or-policy-question": { title: "What can random assignment establish about cause and effect?", bottomLine: "It is powerful for comparing the assigned treatments in the people studied. It does not guarantee good measurement, follow-up, analysis or relevance to other groups. Many questions cannot be tested this way for practical or ethical reasons. Random assignment is a strong design tool, not a complete quality assessment." },
	"do-media-literacy-interventions-reliably-make-everyone-resistant-to-misinformation": { title: "Do media-literacy programs help people recognize misinformation?", bottomLine: "Yes, on average, but results vary by program, audience and follow-up. Some programs also make people distrust accurate news. The useful outcome is better separation of true and false information, not simply more skepticism. No program protects everyone." },
	"do-registered-reports-reduce-publication-bias-and-guarantee-valid-findings": { title: "How do Registered Reports reduce publication bias?", bottomLine: "Journals assess methods before results are known and can agree to publish regardless of the finding. Early comparisons find more null results and favorable quality ratings. The format still cannot guarantee good measurement, faithful execution, enough data, honest reporting or correct interpretation." },
	"can-ordinary-journal-peer-review-reliably-detect-fraud-and-hidden-errors": { title: "How well does journal peer review detect fraud and errors?", bottomLine: "It can improve clarity and catch some problems, but many errors go undetected. Reviewers often lack raw data, time and forensic tools. Studies with planted errors show these limits. Data checks, repeat studies, editorial screening and scrutiny after publication are also needed." },
	"do-direct-replications-often-estimate-smaller-effects-than-original-studies": { bottomLine: "Yes. Several large repeat-study projects in behavioral and social science found smaller average effects and fewer statistically significant results. This does not make every original result false or every repeat study final. Chance, selective publication, context and differences in methods all contribute." },
	"can-flexible-analysis-choices-inflate-false-positive-findings": { bottomLine: "Yes. Trying many outcomes, groups or analysis choices and reporting only the successful result increases false-positive risk. The reported test no longer represents the whole search. Clear advance plans, reporting all paths and adjusting for multiple tests can help." },
	"do-more-facts-alone-reliably-resolve-polarized-science-disputes": { title: "What helps communication across polarized science disputes?", bottomLine: "Accurate evidence is necessary, but facts alone may not settle disputes shaped by identity, values or trust. Who speaks, which questions matter to the audience and whether people can discuss concerns also matter. Recognizing those factors does not make the scientific evidence optional." },
	"does-plain-language-improve-comprehension-without-guaranteeing-an-informed-decision": { title: "Does plain language help people understand scientific information?", bottomLine: "Yes. Clear wording and structure improve access and understanding, especially when health literacy is limited. They do not guarantee an informed decision. Missing information, number skills, available options and personal values still matter. Reading scores alone cannot show that readers understood." },
	"is-one-trusted-messenger-equally-credible-to-every-audience": { title: "How does trust in a scientific messenger vary across audiences?", bottomLine: "People weigh expertise, honesty, shared identity, care and past experience differently. A local clinician may be more trusted than a national expert in one setting, but not another. Familiarity alone does not establish technical accuracy. Both relevant knowledge and audience trust matter." },
	"did-magnetic-stripes-alone-establish-the-modern-theory-of-plate-tectonics": { title: "How did seafloor magnetic stripes help establish plate tectonics?", bottomLine: "Matching stripes on either side of ocean ridges gave a strong test of seafloor spreading. They were one part of the case. Fossils, rocks, earthquakes, volcanoes, ocean-floor ages and measurements of plate motion also converged. The theory rests on several kinds of evidence, not one striking observation." },
	"does-minimum-unit-pricing-reduce-alcohol-consumption-and-harm": { bottomLine: "Yes in the best-evaluated national case. A floor price per unit of alcohol reduced purchases and alcohol-related deaths, especially in groups facing the greatest harm. Effects on hospital admissions are less clear. Results elsewhere depend on prices, income, enforcement and other alcohol policies." },
	"is-alcohol-based-hand-sanitizer-always-equivalent-to-washing-with-soap-and-water": { title: "When is hand sanitizer useful compared with soap and water?", bottomLine: "Alcohol-based sanitizer works well against many germs and is quick to use. Soap and water are better for visibly dirty or greasy hands and for some infections, including norovirus and C. difficile spores. The methods are useful in different settings, not interchangeable for every germ." },
	"does-latent-tuberculosis-infection-always-progress-to-active-disease": { title: "How often does latent tuberculosis become active disease?", bottomLine: "Most people with latent TB never develop active disease and cannot spread TB while it stays latent. Without preventive treatment, lifetime risk is often estimated at 5% to 10%. Risk is higher soon after infection and can be much higher with HIV, immune-suppressing treatment, very young age or other conditions." },
	"can-ketamine-or-esketamine-rapidly-reduce-treatment-resistant-depression": { bottomLine: "Yes, for some people, symptoms can improve within hours or days. Effects after one treatment often fade within days, so further treatment may be needed. Blood-pressure changes, altered perception, misuse risk and uncertain long-term outcomes require clinical monitoring. This is not a simple home cure." },
	"does-maintenance-antipsychotic-treatment-reduce-relapse-in-schizophrenia": { bottomLine: "Yes. Continuing medicine after symptoms stabilize greatly reduces relapse and hospital admission compared with withdrawal or placebo. Side effects can affect movement, metabolism, hormones and heart health. The medicine, dose and duration need personal review. Benefit does not make those risks unimportant." },
	"does-clozapine-reduce-suicidal-behavior-in-schizophrenia-or-schizoaffective-disorder": { bottomLine: "Yes. Clozapine has stronger evidence than other antipsychotics for reducing suicidal behavior in higher-risk patients with these conditions. It also helps some treatment-resistant illness. Serious blood, heart, bowel, seizure and metabolic risks require careful monitoring and clinical management." },
	"does-lithium-prevent-relapse-and-reduce-suicide-risk-in-bipolar-disorder": { bottomLine: "Lithium prevents bipolar relapse. Several reviews also link it to fewer suicides, but the exact effect is less certain because deaths are rare in trials. It needs blood monitoring: toxicity, kidney and thyroid effects, pregnancy and interactions with other medicines all matter." },
	"can-live-video-psychotherapy-work-about-as-well-as-in-person-therapy": { bottomLine: "Often yes for the people and conditions studied, especially structured CBT and PTSD care. Results are generally close to in-person treatment. Privacy, internet access, crisis response, sensory or thinking needs and fit with the therapist still matter. Evidence is thinner for some diagnoses." },
	"does-collaborative-care-improve-depression-and-anxiety-treatment-in-primary-care": { bottomLine: "Yes. A team approach with a primary-care clinician, care manager, specialist advice and planned follow-up modestly improves depression and anxiety outcomes. It works by tracking progress and adjusting treatment. Benefit depends on access, follow-up and how well the team approach is delivered." },
	"can-benzodiazepines-relieve-acute-anxiety-and-should-regular-use-be-stopped-abruptly": { title: "What are the benefits and risks of benzodiazepines for anxiety?", bottomLine: "They can relieve acute anxiety quickly. Regular use can cause physical dependence. Stopping suddenly can cause severe withdrawal, including seizures. Ongoing use needs review, and any reduction usually needs a gradual, personal plan with clinical supervision. Do not abruptly stop regular treatment." },
	"does-combined-hormonal-contraception-increase-the-risk-of-venous-blood-clots": { bottomLine: "Yes. Estrogen-containing contraceptives raise the chance of blood clots in veins, though absolute risk is low for most healthy young users. The product and personal factors matter, including age, smoking, past clots, recent childbirth and inherited clotting risks. Eligibility and alternatives need individual assessment." },
	"do-hormonal-contraceptives-change-cancer-risks-in-different-directions": { bottomLine: "Yes. Use is linked to a small temporary rise in breast-cancer risk and, with longer oral use, higher cervical-cancer risk. Ovarian and uterine-lining cancer risks fall. Effects differ by method, duration, age, screening and time since stopping. One blanket cancer verdict would hide those differences." },
	"are-social-isolation-and-loneliness-linked-to-higher-mortality-in-older-adults": { bottomLine: "Yes. Many studies link isolation and loneliness to higher death rates. These are different experiences, and most evidence observes people rather than assigns treatment. Social connection is a health concern, but trials do not show that any generic social program extends life." },
	"does-moderate-calorie-restriction-improve-health-markers-while-its-effect-on-human-lifespan-remains-unknown": { bottomLine: "A two-year trial in adults without obesity improved several health and aging-related measures. It did not show longer life. Calorie restriction can reduce muscle or bone and may be unsuitable during growth, pregnancy, frailty, eating disorders or some illnesses. Better markers are not proof of a lifespan benefit." },
	"is-metformin-proven-to-extend-healthy-lifespan-in-people-without-diabetes": { title: "Does metformin extend healthy life in people without diabetes?", bottomLine: "That benefit is not established. Metformin helps many people with type 2 diabetes, but animal findings and observational comparisons do not prove longer healthy life in people without it. Side effects include gut problems and vitamin B12 deficiency, with rare serious harms in susceptible patients." },
	"is-rapamycin-proven-to-extend-healthy-human-lifespan": { title: "Does rapamycin extend healthy human lifespan?", bottomLine: "The cited trials do not establish this benefit. Animal studies and small human studies are promising but do not show longer healthy life in people. Immune suppression, infections, mouth ulcers, metabolic effects and drug interactions are concerns. Long-term safety remains uncertain." },
	"do-nad-boosters-raise-nad-without-proven-anti-aging-clinical-benefits": { title: "Do NAD boosters provide anti-aging health benefits?", bottomLine: "A meaningful anti-aging benefit is not established. Some products raise NAD-related compounds in blood or tissues. Trials do not establish longer life or dependable improvements in thinking, strength or daily function in healthy adults. Raising a marker is not the same as improving health. Long-term safety is uncertain." },
	"can-consumer-biological-age-tests-reliably-guide-treatment-or-predict-an-individuals-lifespan": { title: "What can a consumer biological-age test tell you?", bottomLine: "These measures can track disease or death risk across groups and help research. One commercial result cannot reliably predict a person's lifespan or show that a supplement worked. Tests, tissues and algorithms differ, and measurement error matters. Clinical cutoffs and uses are not standardized." },
	"does-early-palliative-care-mean-giving-up-or-shorten-life": { bottomLine: "No. Palliative care can accompany treatment of the illness, including cancer treatment. Starting early can improve symptoms and quality of life and reduce depression or burdensome care. It is not intended to hasten death. Some trials find similar or longer survival." },
	"does-lifelong-exposure-to-high-ldl-cholesterol-causally-drive-atherosclerosis": { bottomLine: "Yes. LDL-containing particles help cause plaque disease in arteries. Both the level and years of exposure matter. Reducing LDL earlier and for longer generally lowers lifetime risk. The right treatment still depends on personal risk, age, other conditions, preferences and treatment burden." },
	"does-raising-hdl-cholesterol-with-medication-reliably-prevent-heart-attacks": { title: "Does raising HDL cholesterol with medicine prevent heart attacks?", bottomLine: "Not reliably when added to effective modern care. Low HDL is linked to heart risk, but simply raising its measured level has not reliably reduced heart attacks. A risk marker is not automatically a useful treatment target." },
	"does-oral-anticoagulation-reduce-stroke-in-atrial-fibrillation-when-indicated": { bottomLine: "Yes, when clot-related stroke risk justifies treatment. Anticoagulant medicines greatly reduce this type of stroke in atrial fibrillation. Bleeding risk, kidney function, other medicines and preferences still matter. Aspirin is not an equivalent substitute." },
	"do-sglt2-inhibitors-slow-chronic-kidney-disease-even-without-diabetes": { bottomLine: "Yes, in many eligible adults, including people without diabetes. These medicines slow kidney disease and reduce some kidney and heart events. They do not suit every kidney condition. Kidney function, urine protein, heart failure, infections, dehydration and acute illness affect prescribing." },
	"can-regular-nsaid-use-injure-the-kidneys": { bottomLine: "Yes. Medicines such as ibuprofen and naproxen can reduce kidney blood flow and cause injury, fluid retention or higher blood pressure. Risk is greater with kidney disease, dehydration, older age, heart failure, higher doses, longer use and certain medicine combinations." },
	"can-abrupt-alcohol-withdrawal-be-medically-dangerous": { bottomLine: "Yes. Sudden stopping or a sharp reduction can cause seizures, hallucinations, delirium and dangerous changes in body functions in someone physically dependent on alcohol. Risk is not a matter of willpower. Heavy regular use, prior severe withdrawal, major illness, pregnancy or worrying symptoms warrant prompt medical assessment." },
	"is-moderate-alcohol-consumption-proven-to-protect-heart-health": { title: "Does moderate drinking protect heart health?", bottomLine: "A causal protective benefit is not established. Some studies find lower heart risk in moderate drinkers, but differences in health, past drinking and measurement can distort that comparison. Major heart bodies do not recommend starting alcohol for health. Alcohol raises risks including cancer, stroke-related conditions, injury and dependence." },
	"are-supervised-consumption-sites-proven-to-reduce-population-overdose-mortality": { title: "How do supervised consumption sites affect overdose deaths?", bottomLine: "They reverse overdoses on site and connect people with care, with very few or no recorded deaths on site. Whether sites reduce deaths across an entire city or region is less clear. Population studies are few, observational and mixed. On-site rescue and population death rates are different outcomes." },
	"are-fentanyl-test-strips-proven-to-prevent-overdose-deaths": { title: "What is known about fentanyl test strips and overdose prevention?", bottomLine: "Strips detect fentanyl in many samples and sometimes prompt safer behavior. Direct evidence of fewer overdose deaths is sparse. A negative result does not make a drug safe. Strips do not measure dose or detect every danger, so they need other risk-reduction measures, including naloxone." },
	"do-solar-panels-consume-more-energy-to-manufacture-than-they-generate": { bottomLine: "No. Modern solar systems usually generate back the energy used to make, install and retire them well within their working life. In suitable locations this commonly takes a few years or less. Technology, manufacturing electricity, sunlight and system lifetime affect the payback." },
	"does-wind-turbine-infrasound-cause-a-distinct-disease-syndrome": { bottomLine: "Evidence does not support a distinct disease syndrome from residential wind-turbine infrasound. Audible noise can still cause annoyance and is linked to reported sleep disturbance. Evidence for long-term clinical effects is thinner. This does not mean residents face no burden; siting and community impacts matter." },
	"are-small-modular-reactors-already-proven-cheaper-and-faster-at-commercial-scale": { title: "Can small modular reactors reduce nuclear construction cost and time?", bottomLine: "Potential benefits are not yet established as a general commercial result. Factory production and repeat builds could help, but smaller units lose economies of scale. Financing, licensing, supply chains and first-of-a-kind costs matter. Results depend on the design, country and sequence of projects." },
	"can-widespread-electric-vehicle-charging-always-fit-existing-local-grids-without-planning": { title: "What grid planning does widespread electric-vehicle charging need?", bottomLine: "Overall demand can be manageable while particular transformers, streets or depots face overloads. Timing and location matter. Forecasting, managed charging, changing prices and targeted upgrades can reduce or delay many constraints. They do not remove the need for every upgrade." },
	"does-ashwagandha-reliably-improve-athletic-performance": { title: "Can ashwagandha improve athletic performance?", bottomLine: "Early studies suggest possible gains in strength, endurance or recovery. Evidence is too limited for a dependable general claim. Studies are often small and short and use different extracts. Product quality, liver or thyroid risks, pregnancy and interactions with medicines also matter." },
	"does-hmb-reliably-add-muscle-or-strength-in-trained-athletes": { title: "Does HMB add strength or muscle in trained athletes?", bottomLine: "Reviews generally do not find meaningful extra gains in trained or competitive athletes. Some untrained, older or poorly nourished groups may benefit modestly. Findings from those groups should not be transferred to trained athletes." },
	"does-tart-cherry-supplementation-speed-recovery-from-hard-exercise": { bottomLine: "It may modestly reduce soreness or help strength recover after unusually damaging exercise. Results are inconsistent, and products and methods vary. It is not an established general performance booster. Sugar, cost, timing, diet and possible effects on training adaptation matter." },
	"does-citrulline-meaningfully-improve-strength-or-power": { bottomLine: "It may modestly improve repetitions or total work in some high-intensity tasks. Results for maximum strength and explosive power are inconsistent. Products, doses and study methods differ, so one positive finding cannot be applied to every citrulline product." },
	"does-glutamine-build-muscle-or-improve-performance-in-healthy-athletes": { bottomLine: "Generally no in healthy athletes with adequate diets. Supplements have not reliably improved muscle, strength or endurance. Glutamine has important roles in the body and can help in selected clinical settings. That does not establish a general sports benefit." },
	"are-multi-ingredient-pre-workout-supplements-proven-safe-and-effective-as-a-category": { title: "What do trials show about multi-ingredient pre-workout supplements?", bottomLine: "Some tested products improve alertness or selected exercise outcomes, often because of caffeine. Results do not apply to every blend. Trials are mostly short and too small to settle rare or long-term harms. Stimulant dose, interactions, product testing and sport rules matter." },
	"is-a-bigger-heat-pump-always-more-efficient": { title: "How does heat-pump size affect efficiency?", bottomLine: "Capacity and efficiency are different. A unit needs to meet the heating load, but excess capacity can lead to short cycles if controls and output range do not suit the home. Size is one factor, not a direct efficiency score." },
	"does-resistance-backup-always-erase-a-heat-pumps-efficiency-benefit": { title: "How does resistance backup affect heat-pump efficiency?", bottomLine: "Occasional backup can coexist with good seasonal efficiency. Extensive backup use can substantially change the result. How much electricity it uses, and when, matters. A warm-year average does not guarantee performance through an extreme winter." },
	"does-water-filter-certification-mean-it-removes-every-contaminant": { title: "What does water-filter certification cover?", bottomLine: "Certification covers a specific product, performance claim and test conditions. Improving taste does not establish removal of lead, PFAS or germs. The exact contaminant listing and performance sheet matter. The filter also needs the stated maintenance." },
	"do-spatial-emanators-prevent-malaria-and-can-they-replace-bed-nets": { title: "Can indoor spatial emanators add protection against malaria?", bottomLine: "Certain products can add to malaria-control programs under WHO's conditional recommendation. They are not established replacements for bed nets or indoor spraying. Suitable products and sustained coverage matter. Evidence does not validate every outdoor gadget or guarantee personal protection from malaria." },
	"can-scientists-attribute-part-of-a-single-extreme-weather-event-to-climate-change": { bottomLine: "Yes, for many kinds of event. Researchers compare today's climate with modeled worlds without human influence. This estimates how warming changed an event's chance or intensity, not whether it was the only cause. Confidence varies by event, region, observations and model quality." },
	"is-climate-change-making-drought-worse-everywhere": { title: "How is climate change affecting drought in different regions?", bottomLine: "Warming has worsened some soil and ecosystem droughts and increased drying in several regions. The trend is not the same everywhere. Rainfall shortages, river flow and soil moisture are different measures. Water use, season and the timescale also affect local drought." },
	"are-climate-tipping-points-guaranteed-to-occur-at-exactly-1-5-degrees-celsius": { title: "How does warming affect the risk of climate tipping points?", bottomLine: "Risk rises with warming, but each system has an uncertain threshold range, not a scheduled switch at exactly 1.5°C. Some systems may enter plausible transition ranges near that level. Changes can take very different lengths of time. This makes 1.5°C a risk boundary, not a universal on-off point." },
	"can-adaptation-alone-avoid-most-climate-damage-without-cutting-emissions": { title: "What are the limits of adapting to climate change?", bottomLine: "Adaptation can save lives and reduce losses. Financial, physical and ecological limits grow as warming rises, and some losses cannot be avoided. Measures that work now may fail or become too costly later. Evidence supports adapting while cutting emissions, not treating one as a substitute for the other." },
	"do-wind-turbines-cause-cancer-or-a-distinct-disease-syndrome-through-infrasound": { title: "Does residential wind-turbine exposure cause cancer?", bottomLine: "Current evidence does not support a cancer link at residential exposure levels. This is not proof that every long-term effect has been ruled out. Audible noise and sleep disturbance remain separate siting concerns." },
	"is-intermittent-fasting-proven-to-extend-human-lifespan-through-autophagy": { title: "Does intermittent fasting extend human lifespan through autophagy?", bottomLine: "This has not been established in people. Fasting can affect cellular recycling and improve some weight or metabolic measures. Human trials mostly measure short-term markers, not lifespan. Animal results vary with species, diet and whether total calories also fall. A plausible mechanism is not proof of longer life." },
	"are-carnivore-diets-proven-safe-and-nutritionally-adequate-over-the-long-term": { title: "What is known about long-term carnivore-diet safety?", bottomLine: "Long-term safety and nutritional adequacy are not established. Evidence relies heavily on self-selected surveys and case reports, not controlled long-term studies. Removing nearly all plant foods can sharply reduce fiber and create nutrient, cholesterol and gut-health concerns. Risks vary with the foods and supplements used." },
	"must-fda-approved-generic-medicines-match-brand-name-quality-and-bioequivalence": { title: "What must U.S. FDA-approved generic medicines match?", bottomLine: "They must match the active ingredient, strength, form, route and intended use, meet quality standards, and show comparable delivery in the body. Inactive ingredients or appearance may differ. This is an accepted testing range, not identity in every detail. Some patients or medicines still need monitoring after a switch." },
	"do-oral-over-the-counter-cough-and-cold-medicines-help-young-children-and-are-they-safe": { title: "What benefits and risks do over-the-counter cough medicines have for young children?", bottomLine: "Reliable benefit is not established in young children, and side effects or dosing mistakes can cause serious harm. U.S. labels say not to use under four. FDA advises against decongestant or antihistamine cough products under two. Honey may help cough only after age one; never give it to younger infants." },
	"can-spinal-manipulation-reliably-treat-asthma-hypertension-or-other-non-musculoskeletal-disease": { title: "Does spinal manipulation treat conditions unrelated to muscles and joints?", bottomLine: "Credible trials do not show dependable benefit for asthma, high blood pressure, infant colic or period pain. Modest benefit for selected back or neck pain is a different finding. Claims about restoring organ function are not supported and should not replace effective medical care." },
	"does-crispr-always-make-only-the-intended-dna-change": { title: "What kinds of unintended changes can occur with CRISPR?", bottomLine: "Changes can occur at unintended sites or in unexpected forms at the intended site. Their frequency varies by product and testing method. Targeting can be precise without being perfect. Clinical products need their own safety evidence rather than a blanket claim about the technology." },
	"can-a-negative-genetic-test-rule-out-every-inherited-disorder": { title: "What does a negative genetic test rule out?", bottomLine: "It means the test found no reportable disease-causing change within what it could detect and interpret. Tests do not cover every kind of change or every condition. Some causes are not yet known. Remaining risk depends on the test and the clinical question." },
	"is-whole-genome-sequencing-of-healthy-adults-proven-to-improve-long-term-health-outcomes": { title: "Does whole-genome screening improve long-term health in healthy adults?", bottomLine: "A broad net benefit is not established. Sequencing finds actionable changes in a minority of people, but more diagnoses do not automatically mean better long-term health. Uncertain results, further tests, cost, anxiety and false reassurance matter. Targeted care based on history and guidelines is a separate comparison." },
	"does-bcg-vaccination-protect-equally-well-against-every-form-of-tuberculosis-at-every-age": { title: "How does BCG protection vary by age and type of tuberculosis?", bottomLine: "Protection is most consistent against severe widespread TB and TB meningitis in young children. Protection against lung TB in teens and adults varies across settings. Countries base use on local TB risk. It should not be treated as equal lifelong protection against every form." },
	"does-a-positive-pcr-result-always-prove-that-a-person-is-currently-infectious": { title: "What does a positive PCR result say about infectiousness?", bottomLine: "It detects genetic material that can remain after live virus has declined. A positive result can show current or recent infection without directly measuring the chance of transmission. Timing, symptoms, immune status, sample quality and the pathogen all matter." },
	"can-symptoms-alone-reliably-distinguish-influenza-covid-19-and-rsv": { title: "Can symptoms distinguish flu, COVID-19 and RSV?", bottomLine: "Not reliably. Fever, cough, tiredness and breathing symptoms overlap. Age, season and exposure change the odds but do not settle the diagnosis. Testing is often needed when the result affects treatment, infection-control advice or care for a higher-risk person." },
	"is-sleep-hygiene-alone-an-effective-treatment-for-chronic-insomnia": { title: "How does sleep-hygiene advice compare with CBT-I for chronic insomnia?", bottomLine: "Good sleep habits can support sleep, but advice about them alone is not the recommended treatment for chronic insomnia. CBT-I combines structured work on behavior and thoughts about sleep and has stronger evidence. A useful routine is not the same intervention as a full treatment program." },
	"does-irregular-sleep-timing-matter-even-when-total-sleep-duration-seems-adequate": { bottomLine: "Probably. Large studies link irregular sleep to worse health even after accounting for average sleep length. Lab studies also find effects of body-clock disruption. But illness, shift work, stress and caring duties can explain part of the association. The long-term benefit of changing regularity is less certain than the link." },
	"can-a-custom-oral-appliance-treat-obstructive-sleep-apnea-when-cpap-is-not-tolerated-or-preferred": { bottomLine: "Yes, for many adults. A custom, adjustable jaw-positioning device from a qualified dentist can reduce breathing pauses and symptoms. Guidelines support it when CPAP is not tolerated or an alternative is preferred. CPAP usually reduces pauses more, while comfort and consistent use affect real-world benefit." },
	"can-unusual-animal-behavior-reliably-predict-earthquakes": { title: "Can unusual animal behavior predict earthquakes?", bottomLine: "No reliable prediction method is established. Animals can notice weak shaking before people do, but that is not prediction before an earthquake starts. Reports usually look back after an event. They rarely test advance predictions of time, place and magnitude against false alarms and ordinary behavior." },
	"does-killing-predators-reliably-protect-livestock-or-biodiversity": { title: "When does removing predators protect livestock or biodiversity?", bottomLine: "Targeted removal can reduce specific threats, especially from invasive predators on islands. Broad culling can fail, remove animals causing no problem or disrupt ecosystems. Effects depend on species, place, scale and the alternative protections used. A result in one setting does not validate culling in every setting." },
	"is-suppressing-every-fire-best-for-fire-adapted-ecosystems": { title: "How does fire suppression affect fire-adapted ecosystems?", bottomLine: "Excluding fire can change habitat, build up fuels and harm species that depend on recurring fire. That does not make every fire beneficial. Timing, intensity, frequency, weather and human exposure determine both ecological effects and safety. Fire management needs to suit the ecosystem and local risks." },
	"do-genetically-modified-crops-always-increase-pesticide-use": { title: "How do genetically modified crops affect pesticide use?", bottomLine: "The effect depends on the trait, crop and farming system. Insect-resistant crops have often reduced insecticide use. Herbicide-tolerant systems change herbicide use and can select resistant weeds that need more control. Genetic engineering is not one pesticide strategy, so there is no single direction for all crops." },
	"does-agroforestry-reliably-improve-farms-and-ecosystems-at-the-same-time": { title: "What are the benefits and trade-offs of agroforestry?", bottomLine: "Combining trees with crops or livestock can add habitat, carbon storage, shade and products. Trees can also compete for light or water, delay returns or complicate farming. Species, climate, soils, land rights and markets matter. Benefits depend on what the new system replaces." },
	"does-adding-biochar-to-soil-always-increase-crop-yields-and-lock-away-carbon": { title: "How do biochar effects on crop yields and carbon storage vary?", bottomLine: "Some biochars persist for long periods and improve some soils or yields. Other trials find little benefit or harm. Climate benefit depends on the source material, production, transport, soil response and how long carbon remains stored. What would otherwise happen to the biomass matters too." },
	"is-grass-fed-beef-always-lower-carbon-than-feedlot-finished-beef": { title: "How do climate emissions compare for grass-fed and feedlot-finished beef?", bottomLine: "Many lifecycle comparisons do not find lower emissions for grass-fed beef. Grazing can improve some soils, but grass finishing usually needs more land and time and can produce more methane per unit of beef. Soil history, feed, productivity and accounting choices affect the comparison." },
	"is-cultivated-meat-already-proven-greener-than-conventional-meat-at-commercial-scale": { title: "What determines cultivated meat's environmental footprint at scale?", bottomLine: "Lower land use is possible, but large-scale environmental benefits are not established. Existing assessments rely on future production assumptions. Electricity, materials, factory efficiency and the meat used for comparison can reverse climate results. A projected benefit is not a measured commercial outcome." },
	"does-ocean-acidification-affect-every-marine-organism-in-the-same-way": { title: "How do ocean-acidification effects differ across marine organisms?", bottomLine: "Effects vary by species, life stage and habitat. Lower pH and less available carbonate can harm shells, skeletons, development and food webs. Some organisms tolerate or benefit from particular changes. That variation does not cancel risks to sensitive species and ecosystems." },
	"is-aquaculture-always-more-sustainable-than-catching-wild-seafood": { title: "How do environmental impacts compare for farmed and wild seafood?", bottomLine: "Species and production methods matter more than the farmed-or-wild label. Farmed shellfish and seaweed can have low impacts. Some fish farms have substantial feed, pollution or habitat costs. Wild fisheries range from well-managed harvests to depleted stocks, heavy fuel use and damaging bycatch." },
	"are-sunscreen-chemicals-proven-to-be-a-major-cause-of-coral-reef-decline-in-the-ocean": { title: "What is known about sunscreen chemicals and coral-reef harm?", bottomLine: "Some chemicals harm corals in lab studies. Their real-world exposure and long-term effects on reefs are less clear. Evidence does not establish sunscreen as a leading global driver on the scale of warming, acidification or other major stresses. Reducing local pollution need not mean abandoning sun protection." },
	"is-ocean-iron-fertilization-proven-to-provide-safe-durable-carbon-removal-at-climate-scale": { title: "Can ocean iron fertilization provide durable carbon removal?", bottomLine: "A bloom of plankton is not proof of lasting carbon removal. The amount reaching deep storage, effects elsewhere and risks to oxygen and food webs remain uncertain. Monitoring, scale, cost and extra emissions also matter. The cited evidence supports research, not an established climate service." },
	"will-quantum-computers-make-every-computational-problem-faster": { title: "Which kinds of problems can quantum computers speed up?", bottomLine: "Some algorithms offer large speedups for particular structures, such as factoring with suitable fault-tolerant hardware. Many tasks have no known quantum advantage. Inputs, error correction, communication and strong classical alternatives can dominate practical performance. Quantum computing is not a universal speed multiplier." },
	"is-the-ph-scale-always-limited-to-values-from-zero-to-fourteen": { title: "Can pH fall below zero or rise above fourteen?", bottomLine: "Yes. The familiar 0-to-14 range is an approximation for dilute water-based solutions near room temperature. Concentrated strong acids and bases can fall outside it. pH measures hydrogen-ion activity, and temperature, solvent and measurement conventions matter. Even neutral pH is not always exactly seven." },
	"can-a-finite-physical-process-reach-absolute-zero-temperature": { bottomLine: "No under the usual third-law limit. Experiments can get extremely close to zero kelvin, but removing the remaining entropy becomes harder and harder. Reaching exactly zero would require unlimited time, steps or resources, or an idealized process. A more powerful refrigerator does not remove this limit." },
	"does-microcredit-reliably-lift-most-borrowers-out-of-poverty": { title: "How does microcredit affect poverty?", bottomLine: "Small loans help some people run businesses or manage cash flow. Trials do not find large average reductions in poverty or broad gains for most borrowers. Results depend on existing businesses, goals, loan terms, markets and repayment pressure. Access to credit and escape from poverty are different outcomes." },
	"do-child-benefits-reduce-child-poverty-without-any-labor-supply-tradeoff": { title: "How do child benefits affect poverty and parents' work?", bottomLine: "Cash benefits can substantially reduce measured child poverty when they reach families and are large enough. Effects on work vary from little change to reductions for some carers. Eligibility, payment size, taxes, childcare access and household circumstances affect the trade-off." },
	"does-putting-a-price-on-carbon-reduce-greenhouse-gas-emissions": { bottomLine: "Yes. Carbon taxes and emissions-trading systems generally reduce the emissions they cover compared with credible estimates of what would otherwise happen. Results vary with price, coverage and enforcement. Revenue use, fairness, other policies and political stability also matter. A weak price with loopholes does less." },
	"can-congestion-pricing-reduce-urban-traffic-without-creating-equity-concerns": { title: "How does congestion pricing affect traffic and fairness?", bottomLine: "Charges can reduce traffic, delays and some pollution in busy areas. Who pays and benefits depends on income, disability, work, transport options and how revenue is used. Fairness is not guaranteed by the policy label. It needs measurement in the actual scheme." },
	"do-labor-unions-raise-members-wages-and-reduce-wage-inequality-without-tradeoffs": { title: "How do labor unions affect pay and employment?", bottomLine: "Unions generally raise covered workers' pay and benefits and narrow wage gaps. Effects on hiring, investment, productivity and other workers vary. Bargaining rules, industry, management and the wider economy shape the result. Higher member pay does not establish that every other effect is favorable." },
	"do-child-care-subsidies-always-cause-large-increases-in-maternal-employment": { title: "How do child-care subsidies affect mothers' employment?", bottomLine: "Lower childcare prices generally increase employment on average, but effects range from large to near zero. Subsidies may replace care a family already used rather than enable new work. Supply, quality, hours, wages, eligibility and the child's age all affect the response." }
};

export function completeEditorialCopy(seed: CompleteSeedClaim): CompleteSeedClaim {
	const correction = editorialCopy[seed.slug];
	const sources = correctedSources(seed);
	const living = clinicalMaintenanceTopics.has(seed.topicSlug) && seed.reviewMode !== "living";
	const commentary = isRevisionCommentary(seed.editorSummary);
	const unsupportedAppraisal = unsupportedAppraisalClaims.has(seed.slug);
	if (!correction && sources === seed.sources && !living && !commentary && !unsupportedAppraisal) return seed;
	const title = correction?.title ?? seed.title;
	const bottomLine = correction?.bottomLine ?? seed.bottomLine;
	return {
		...seed,
		title,
		bottomLine,
		sources,
		reviewMode: living ? "living" : seed.reviewMode,
		editorSummary: commentary ? seed.stableCore[0]! : seed.editorSummary,
		appraisalTools: unsupportedAppraisal ? [] : seed.appraisalTools,
		reviewerLine: correction ? "Lead wording edited with AI assistance against the existing source record. Independent expert review is not documented." : seed.reviewerLine,
		evidenceSummaries: seed.evidenceSummaries.map(summary => summary.question === seed.title && summary.finding === seed.bottomLine && summary.population?.startsWith("Public-facing summary built from") ? { ...summary, question: title, finding: bottomLine } : summary),
		changeLog: [...seed.changeLog, { date: editorialCompletionPreparedAt, kind: "update", summary: sources !== seed.sources ? "Verified selected source metadata or added the specified surveillance study. No new comprehensive evidence review or independent expert appraisal is claimed." : correction ? "Clarified the question and lead answer while retaining scientific qualifications. This wording change is not a new evidence review." : "Corrected recorded editorial metadata or added a living-review maintenance classification. No new evidence review is claimed." }]
	};
}
